local capitalize = 0
return {
   emph = {
     enter = function(e)
       capitalize = capitalize + 1
     end,
     exit = function(e)
       capitalize = capitalize - 1
     end,
   },
   str = function(e)
     if capitalize > 0 then
       e.text = e.text:upper()
      end
   end
}

return {
  str = function(e)
    e.text = e.text:upper()
  end,
  footnote = {
    enter = function(e)
      return true  -- prevent traversing into children
    end
  }
}

